    if (vertices.isEmpty()) {
        return true;
    }
    for (V vertex : vertices) {
        Set<V> neighbors = graph.neighborListOf(vertex);
        if (neighbors.size() != vertices.size() - 1) {
            return false;
        }
        for (V neighbor : neighbors) {
            if (!vertices.contains(neighbor)) {
                return false;
            }
        }
    }
    return true;
}

